package com.brainserve.onboarding.notifications.infrastructure.persistence;
import com.brainserve.onboarding.notifications.domain.model.NotificationTemplate;import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface NotificationTemplateRepository extends JpaRepository<NotificationTemplate,UUID>{Optional<NotificationTemplate> findByOrganizationIdAndId(UUID org,UUID id);Optional<NotificationTemplate> findByOrganizationIdAndEventTypeAndStatus(UUID org,String eventType,String status);Page<NotificationTemplate> findAllByOrganizationId(UUID org,Pageable p);boolean existsByOrganizationIdAndCode(UUID org,String code);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select t from NotificationTemplate t where t.organizationId=:org and t.id=:id")Optional<NotificationTemplate> findForUpdate(@Param("org")UUID org,@Param("id")UUID id);}
